#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> minx(n), miny(n);
    int max_width = 0, max_height = 0;

    for (int i = 0; i < n; ++i) {
        int k;
        cin >> k;
        int cur_minx = INT_MAX, cur_maxx = INT_MIN;
        int cur_miny = INT_MAX, cur_maxy = INT_MIN;
        for (int j = 0; j < k; ++j) {
            int x, y;
            cin >> x >> y;
            cur_minx = min(cur_minx, x);
            cur_maxx = max(cur_maxx, x);
            cur_miny = min(cur_miny, y);
            cur_maxy = max(cur_maxy, y);
        }
        minx[i] = cur_minx;
        miny[i] = cur_miny;
        int width = cur_maxx - cur_minx + 1;
        int height = cur_maxy - cur_miny + 1;
        max_width = max(max_width, width);
        max_height = max(max_height, height);
    }

    long long W = 1LL * n * max_width;
    long long H = max_height;
    cout << W << ' ' << H << '\n';

    for (int i = 0; i < n; ++i) {
        long long base_x = 1LL * i * max_width;
        long long X = base_x - minx[i];
        long long Y = 0LL - miny[i];
        cout << X << ' ' << Y << " 0 0\n";
    }

    return 0;
}
